"""
Gerador de Photocards em Folha A4 (Word)
=========================================
App em Streamlit para montar uma folha A4 com vários photocards
(imagens no tamanho padrão de cartão) e exportar o resultado como
um documento Word (.docx) pronto para imprimir e recortar.

Como rodar:
    pip install streamlit python-docx pillow
    streamlit run photocard_app.py
"""

import io
import math
from dataclasses import dataclass

import streamlit as st
from PIL import Image, ImageOps

from docx import Document
from docx.shared import Cm, Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

# ---------------------------------------------------------------------------
# Configurações da página A4
# ---------------------------------------------------------------------------
A4_WIDTH_CM = 21.0
A4_HEIGHT_CM = 29.7

PRESETS = {
    "Photocard padrão K-pop (5,4 x 8,6 cm)": (5.4, 8.6),
    "Cartão colecionável (6,3 x 8,8 cm)": (6.3, 8.8),
    "Polaroid mini (5,4 x 8,6 cm)": (5.4, 8.6),
    "Cartão de visita (5,0 x 9,0 cm)": (5.0, 9.0),
    "Personalizado": None,
}

# Logo do ateliê (embutido em base64 para o app funcionar em um único arquivo)
LOGO_BASE64 = ""

# Paleta de cores extraida do logotipo "Atelie Livia Card"
COLOR_CREAM = "#faf6ee"
COLOR_CREAM_SOFT = "#fdfaf5"
COLOR_BLUSH = "#f8e7e1"
COLOR_ROSE = "#cf9a8d"
COLOR_ROSE_DARK = "#b97e70"
COLOR_BLUE = "#d8e1e9"
COLOR_GOLD = "#c9a165"
COLOR_BROWN = "#3c2724"
COLOR_BROWN_SOFT = "#6b5a54"

