st.set_page_config(page_title="Ateliê Lívia Card | Photocards A4", page_icon="🌸", layout="wide")


# ---------------------------------------------------------------------------
# Funções auxiliares para o Word (python-docx)
# ---------------------------------------------------------------------------
def _set_cell_margins(cell, top=0, bottom=0, left=0, right=0):
    tc_pr = cell._tc.get_or_add_tcPr()
    mar = OxmlElement("w:tcMar")
    for tag, value in (("top", top), ("bottom", bottom), ("start", left), ("end", right)):
        node = OxmlElement(f"w:{tag}")
        node.set(qn("w:w"), str(int(value * 567)))  # cm -> dxa (twips)
        node.set(qn("w:type"), "dxa")
        mar.append(node)
    tc_pr.append(mar)


def _set_cell_border(cell, style="dashed", size=4, color="999999"):
    tc_pr = cell._tc.get_or_add_tcPr()
    borders = OxmlElement("w:tcBorders")
    for edge in ("top", "left", "bottom", "right"):
        el = OxmlElement(f"w:{edge}")
        el.set(qn("w:val"), style)
        el.set(qn("w:sz"), str(size))
        el.set(qn("w:space"), "0")
        el.set(qn("w:color"), color)
        borders.append(el)
    tc_pr.append(borders)


def _set_table_fixed_layout(table, gap_cm):
    tbl_pr = table._tbl.tblPr
    layout = OxmlElement("w:tblLayout")
    layout.set(qn("w:type"), "fixed")
    tbl_pr.append(layout)
    if gap_cm > 0:
        spacing = OxmlElement("w:tblCellSpacing")
        spacing.set(qn("w:w"), str(int(gap_cm * 567)))
        spacing.set(qn("w:type"), "dxa")
        tbl_pr.append(spacing)


def _fit_image_cover(img: Image.Image, target_ratio: float) -> Image.Image:
    """Corta a imagem (mantendo o centro) para bater com a proporção do cartão,
    evitando que a foto fique distorcida ao ser redimensionada no Word."""
    img = ImageOps.exif_transpose(img)
    w, h = img.size
    img_ratio = w / h
    if img_ratio > target_ratio:
        new_w = int(h * target_ratio)
        left = (w - new_w) // 2
        img = img.crop((left, 0, left + new_w, h))
    else:
        new_h = int(w / target_ratio)
        top = (h - new_h) // 2
        img = img.crop((0, top, w, top + new_h))
    return img


@dataclass
class CardSpec:
    width_cm: float
    height_cm: float
    cols: int
    rows: int
    gap_cm: float
    margin_cm: float
    cut_lines: bool
    labels: list


def build_docx(images: list, spec: CardSpec) -> io.BytesIO:
    doc = Document()
    section = doc.sections[0]
    section.page_width = Cm(A4_WIDTH_CM)
    section.page_height = Cm(A4_HEIGHT_CM)
    section.top_margin = Cm(spec.margin_cm)
    section.bottom_margin = Cm(spec.margin_cm)
    section.left_margin = Cm(spec.margin_cm)
    section.right_margin = Cm(spec.margin_cm)

    per_page = spec.cols * spec.rows
    total_slots = max(per_page, len(images))
    total_pages = math.ceil(total_slots / per_page)

    target_ratio = spec.width_cm / spec.height_cm
    idx = 0

    for page in range(total_pages):
        table = doc.add_table(rows=spec.rows, cols=spec.cols)
        table.alignment = WD_TABLE_ALIGNMENT.CENTER
        _set_table_fixed_layout(table, spec.gap_cm)

        for r in range(spec.rows):
            table.rows[r].height = Cm(spec.height_cm)
            for c in range(spec.cols):
                cell = table.cell(r, c)
                cell.width = Cm(spec.width_cm)
                _set_cell_margins(cell)
                if spec.cut_lines:
                    _set_cell_border(cell)

                para = cell.paragraphs[0]
                para.alignment = WD_ALIGN_PARAGRAPH.CENTER
                para.paragraph_format.space_before = Pt(0)
                para.paragraph_format.space_after = Pt(0)

                if idx < len(images):
                    pil_img = _fit_image_cover(images[idx], target_ratio)
                    buf = io.BytesIO()
                    pil_img.convert("RGB").save(buf, format="JPEG", quality=92)
                    buf.seek(0)
                    run = para.add_run()
                    run.add_picture(buf, width=Cm(spec.width_cm), height=Cm(spec.height_cm))

                    if spec.labels and idx < len(spec.labels) and spec.labels[idx]:
                        label_para = cell.add_paragraph(spec.labels[idx])
                        label_para.alignment = WD_ALIGN_PARAGRAPH.CENTER
                        label_para.paragraph_format.space_before = Pt(1)
                        for run_l in label_para.runs:
                            run_l.font.size = Pt(7)

                    idx += 1

        if page < total_pages - 1:
            doc.add_page_break()

    out = io.BytesIO()
    doc.save(out)
    out.seek(0)
    return out


# ---------------------------------------------------------------------------
# Interface Streamlit
# ---------------------------------------------------------------------------
st.markdown(CUSTOM_CSS, unsafe_allow_html=True)

st.markdown(
    f"""
    <div class="brand-header">
        <img src="data:image/png;base64,{LOGO_BASE64}" />
        <p>Gerador de photocards para folha A4</p>
    </div>
    """,
    unsafe_allow_html=True,
)
st.caption(
    "Monte uma folha A4 cheia de photocards a partir das suas imagens e baixe "
    "o resultado pronto em .docx, formatado para impressão e recorte."
)

with st.sidebar:
    st.markdown(
        f"""
        <div class="sidebar-logo">
            <img src="data:image/png;base64,{LOGO_BASE64}" />
        </div>
        """,
        unsafe_allow_html=True,
    )
    st.header("⚙️ Configurações do cartão")

    preset_name = st.selectbox("Formato do cartão", list(PRESETS.keys()))
    if PRESETS[preset_name] is not None:
        default_w, default_h = PRESETS[preset_name]
    else:
        default_w, default_h = 5.4, 8.6

    col_a, col_b = st.columns(2)
    card_w = col_a.number_input("Largura (cm)", min_value=1.0, max_value=20.0, value=default_w, step=0.1)
    card_h = col_b.number_input("Altura (cm)", min_value=1.0, max_value=29.0, value=default_h, step=0.1)

    margin_cm = st.slider("Margem da folha (cm)", 0.0, 3.0, 1.0, 0.1)
    gap_cm = st.slider("Espaço entre cartões (cm)", 0.0, 2.0, 0.3, 0.1)

    usable_w = A4_WIDTH_CM - 2 * margin_cm
    usable_h = A4_HEIGHT_CM - 2 * margin_cm
    max_cols = max(1, int((usable_w + gap_cm) // (card_w + gap_cm)))
    max_rows = max(1, int((usable_h + gap_cm) // (card_h + gap_cm)))

    st.caption(f"Cabem até **{max_cols} colunas × {max_rows} linhas** ({max_cols * max_rows} cartões/folha) com esses valores.")

    col_c, col_d = st.columns(2)
    cols = col_c.number_input("Colunas", min_value=1, max_value=10, value=max_cols)
    rows = col_d.number_input("Linhas", min_value=1, max_value=10, value=max_rows)

    if cols > max_cols or rows > max_rows:
        st.warning("Essa quantidade de colunas/linhas pode ultrapassar a folha A4.")

    cut_lines = st.checkbox("Mostrar linhas de corte tracejadas", value=True)
    add_labels = st.checkbox("Adicionar legenda (nome) abaixo de cada cartão", value=False)

st.subheader("1. Envie as imagens dos photocards")
uploaded_files = st.file_uploader(
    "Selecione uma ou mais imagens (JPG/PNG/JFIF)",
    type=["jpg", "jpeg", "png", "jfif"],
    accept_multiple_files=True,
)

images = []
labels = []
if uploaded_files:
    st.subheader("2. Pré-visualização")
    preview_cols = st.columns(min(len(uploaded_files), 6) or 1)
    for i, file in enumerate(uploaded_files):
        img = Image.open(file)
        images.append(img)
        with preview_cols[i % len(preview_cols)]:
            st.image(img, width="stretch")
            if add_labels:
                default_name = file.name.rsplit(".", 1)[0]
                label = st.text_input(f"Legenda {i + 1}", value=default_name, key=f"label_{i}")
                labels.append(label)

    per_page = int(cols) * int(rows)
    total_pages = math.ceil(max(per_page, len(images)) / per_page)
    st.info(f"📄 {len(images)} imagem(ns) → {total_pages} folha(s) A4, {per_page} cartão(ões) por folha.")

    st.subheader("3. Gerar documento Word")
    if st.button("Gerar arquivo .docx", type="primary"):
        spec = CardSpec(
            width_cm=card_w,
            height_cm=card_h,
            cols=int(cols),
            rows=int(rows),
            gap_cm=gap_cm,
            margin_cm=margin_cm,
            cut_lines=cut_lines,
            labels=labels if add_labels else [],
        )
        with st.spinner("Montando a folha A4..."):
            docx_bytes = build_docx(images, spec)
        st.success("Documento gerado com sucesso!")
        st.download_button(
            label="⬇️ Baixar photocards.docx",
            data=docx_bytes,
            file_name="photocards_a4.docx",
            mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        )
else:
    st.info("Envie ao menos uma imagem para começar.")
